#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/postgres-16-alpine-arm64-oci ] || "$F" docker.io/library/postgres sha256:40e58641410e030f5769096bca8372f68f243e1859c8ecdf11f227da390d514d postgres:16-alpine images/postgres-16-alpine-arm64-oci
[ "$A" = arm64 ] || [ -f images/postgres-16-alpine-amd64.docker.tar ] || "$F" docker.io/library/postgres sha256:a2f7e20374cd8fd8ed4a588b79549e10589bea7b1686e77922f5ac741b80b8a1 postgres:16-alpine images/postgres-16-alpine-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/temporalio-admin-tools-1.32.2-arm64-oci ] || "$F" docker.io/temporalio/admin-tools sha256:df920de90e0d8a02bd65480524de7e76addc0b6c889696d76229f8c507c90e84 temporalio/admin-tools:1.32.2 images/temporalio-admin-tools-1.32.2-arm64-oci
[ "$A" = arm64 ] || [ -f images/temporalio-admin-tools-1.32.2-amd64.docker.tar ] || "$F" docker.io/temporalio/admin-tools sha256:d6655e288364110b61204fbae5f103232b2c5c78e647a27bc11603d274145809 temporalio/admin-tools:1.32.2 images/temporalio-admin-tools-1.32.2-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/temporalio-server-1.32.2-arm64-oci ] || "$F" docker.io/temporalio/server sha256:a2d55f913eb0f646dd6d8026d02a3f851b87051beaa6d0be57be44c51506ee7b temporalio/server:1.32.2 images/temporalio-server-1.32.2-arm64-oci
[ "$A" = arm64 ] || [ -f images/temporalio-server-1.32.2-amd64.docker.tar ] || "$F" docker.io/temporalio/server sha256:3e11544607762c3187c12a63e289e03beddf46c21ebb52b47ccb77db179d6313 temporalio/server:1.32.2 images/temporalio-server-1.32.2-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/alpine-3.22-arm64-oci ] || "$F" docker.io/library/alpine sha256:e233f2058b0628266762f745a2c17e623b418e0090f47d223909d1f9a7d4367e alpine:3.22 images/alpine-3.22-arm64-oci
[ "$A" = arm64 ] || [ -f images/alpine-3.22-amd64.docker.tar ] || "$F" docker.io/library/alpine sha256:9db2934886712d877c932e07249c75a59e6ca27adfbccc05261987a17bef2d63 alpine:3.22 images/alpine-3.22-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/alpine-3.22-amd64.docker.tar images/postgres-16-alpine-amd64.docker.tar images/temporalio-admin-tools-1.32.2-amd64.docker.tar images/temporalio-server-1.32.2-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/alpine-3.22-arm64-oci images/postgres-16-alpine-arm64-oci images/temporalio-admin-tools-1.32.2-arm64-oci images/temporalio-server-1.32.2-arm64-oci
